  Lax330177.UniformCosts.Uniform q c → Eq p.elapsed (instHAdd.hAdd p.waiting (instHMul.hMul p.hops c))

path_trail : ∀ {n k : Nat} {G : Lax330177.Representations.Graph n} {mode : Lax330177.Representations.TraversalMode}
  (d : Lax330177.Representations.Direction) (w : Lax330177.Paths.Walk G mode k),
  w.IsPath → Lax330177.Paths.Walk.IsStaticEdgeTrail d w

trail_inclusion : ∀ {n k : Nat} {G : Lax330177.Representations.Graph n} {mode : Lax330177.Representations.TraversalMode}
  (d : Lax330177.Representations.Direction) (w : Lax330177.Paths.Walk G mode k),
  Lax330177.Paths.Walk.IsStaticEdgeTrail d w → Lax330177.Paths.Walk.IsTemporalEdgeTrail d w

zero_optima : ∀ {n : Nat} {G : Lax330177.Representations.Graph n} {q : Lax330177.OptimalPaths.Query G}
  (p : Lax330177.OptimalPaths.Candidate q),
